"use client";
import { useEffect, useState } from "react";
import { AppShell } from "@/components/layout/app-shell";
import { Card } from "@/components/ui/card";
import { apiFetch } from "@/lib/api";

type Connection = { id: string; provider: string; baseUrl?: string | null; enabled: boolean; configured: boolean; lastConnectedAt?: string | null; lastSyncedAt?: string | null };
export default function IntegrationsPage() { const [items, setItems] = useState<Connection[]>([]); const [url, setUrl] = useState(""); const [message, setMessage] = useState(""); const load = () => void apiFetch<Connection[]>("/integrations").then(setItems).catch((e) => setMessage(e instanceof Error ? e.message : "Unable to load integrations.")); useEffect(load, []); const save = async () => { try { await apiFetch("/integrations/website/configure", { method: "POST", body: JSON.stringify({ baseUrl: url, enabled: true }) }); setMessage("Website integration saved. Credentials remain server-side."); setUrl(""); load(); } catch (e) { setMessage(e instanceof Error ? e.message : "Unable to configure integration."); } }; const test = async () => { try { const result = await apiFetch<{ status: string }>("/integrations/website/test", { method: "POST" }); setMessage(`Connection test: ${result.status}`); load(); } catch (e) { setMessage(e instanceof Error ? e.message : "Connection test failed."); } }; const sync = async () => { try { const result = await apiFetch<{ status: string; recordsProcessed?: number; recordsCreated?: number; recordsUpdated?: number }>("/integrations/website/sync", { method: "POST" }); setMessage(`Sync ${result.status}: ${result.recordsProcessed ?? 0} processed, ${result.recordsCreated ?? 0} created, ${result.recordsUpdated ?? 0} updated.`); load(); } catch (e) { setMessage(e instanceof Error ? e.message : "Synchronisation failed."); } }; return <AppShell title="Integrations" description="Connect external systems through secure server-side adapters."><section className="space-y-5"><div><p className="text-sm font-semibold uppercase tracking-[0.16em] text-brand-500">Connected systems</p><h1 className="mt-2 text-3xl font-semibold text-ink">Integrations</h1></div><Card className="p-5"><h2 className="font-semibold">Website</h2><p className="mt-1 text-sm text-slate-500">Provide the website API or integration endpoint after its technology has been assessed.</p><div className="mt-4 flex flex-col gap-3 md:flex-row"><input value={url} onChange={(e) => setUrl(e.target.value)} placeholder="https://example.com/api/health" className="flex-1 rounded-xl border border-line px-3 py-2" /><button onClick={() => void save()} disabled={!url} className="rounded-xl bg-brand-500 px-4 py-2 font-semibold text-white disabled:opacity-50">Configure</button><button onClick={() => void test()} className="rounded-xl border border-line px-4 py-2 font-semibold">Test connection</button><button onClick={() => void sync()} className="rounded-xl border border-line px-4 py-2 font-semibold">Sync now</button></div>{message && <p className="mt-3 text-sm text-slate-600">{message}</p>}</Card><Card className="p-5"><h2 className="font-semibold">Configured connections</h2><div className="mt-4 space-y-3">{items.map((item) => <div key={item.id} className="flex items-center justify-between rounded-xl border border-line p-3"><div><p className="font-semibold">{item.provider}</p><p className="text-xs text-slate-500">{item.baseUrl ?? "No endpoint"}</p></div><span className="text-xs font-semibold">{item.configured ? `Configured${item.lastSyncedAt ? ` · synced ${new Date(item.lastSyncedAt).toLocaleDateString()}` : ""}` : "Needs setup"}</span></div>)}{items.length === 0 && <p className="text-sm text-slate-500">No integrations configured.</p>}</div></Card></section></AppShell>; }
